- 后续需求在此基线上增量实现。

"""Change-impact analysis over a field lineage graph.

The public entry point is :func:`analyze_change_impact`. It receives a
lineage graph of field nodes connected by directed dependency edges, the
set of fields about to change and a set of validation rules. It reports
which downstream fields and which rules are affected by the change, and
for every affected rule the reason path proving it.

An edge ``{"source": left, "target": right}`` means the right-side field
depends on the left-side field, so change impact travels along edges in
their declared direction (``source`` -> ``target``).

Every structural or referential problem is reported as a failure result
``{"code": "INVALID_ARGUMENT", "message": ..., "data": None}`` rather
than raised; successful analysis returns
``{"code": "OK", "message": None, "data": {...}}``.
"""

from __future__ import annotations

from collections import deque
from typing import Any, Dict, List, Optional, Set, Tuple

__all__ = ["analyze_change_impact"]

OK = "OK"
INVALID_ARGUMENT = "INVALID_ARGUMENT"

_NODE_KEYS = frozenset({"id", "object", "name"})
_EDGE_KEYS = frozenset({"source", "target"})
_RULE_KEYS = frozenset({"id", "field", "description", "severity"})


def _failure(message: str) -> Dict[str, Any]:
    return {"code": INVALID_ARGUMENT, "message": message, "data": None}


def _check_keys(value: Dict[str, Any], required: frozenset, where: str) -> Optional[Dict[str, Any]]:
    keys = set(value)
    if keys == required:
        return None
    missing = sorted(required - keys)
    if missing:
        return _failure(f"{where} is missing keys: {missing}")
    unknown = sorted(keys - required)
    return _failure(f"{where} has unsupported keys: {unknown}")


def _validate_graph(graph: Any) -> Tuple[Optional[Set[str]], Optional[Dict[str, Any]]]:
    if not isinstance(graph, dict):
        return None, _failure("graph must be an object with 'nodes' and 'edges'")
    if "nodes" not in graph:
        return None, _failure("graph is missing 'nodes'")
    if "edges" not in graph:
        return None, _failure("graph is missing 'edges'")

    nodes = graph["nodes"]
    edges = graph["edges"]
    if not isinstance(nodes, list):
        return None, _failure("graph.nodes must be a list of field nodes")
    if not isinstance(edges, list):
        return None, _failure("graph.edges must be a list of dependency edges")

    declared: Set[str] = set()
    for index, node in enumerate(nodes):
        if not isinstance(node, dict):
            return None, _failure(f"graph.nodes[{index}] must be an object")
        key_error = _check_keys(node, _NODE_KEYS, f"graph.nodes[{index}]")
        if key_error is not None:
            return None, key_error
        node_id = node["id"]
        if not isinstance(node_id, str) or not node_id:
            return None, _failure(
                f"graph.nodes[{index}].id must be a non-empty string"
            )
        if not isinstance(node["object"], str) or not node["object"]:
            return None, _failure(
                f"graph.nodes[{index}].object must be a non-empty string"
            )
        if not isinstance(node["name"], str) or not node["name"]:
            return None, _failure(
                f"graph.nodes[{index}].name must be a non-empty string"
            )
        if node_id in declared:
            return None, _failure(f"duplicate field node id: {node_id!r}")
        declared.add(node_id)

    for index, edge in enumerate(edges):
        if not isinstance(edge, dict):
            return None, _failure(f"graph.edges[{index}] must be an object")
        key_error = _check_keys(edge, _EDGE_KEYS, f"graph.edges[{index}]")
        if key_error is not None:
            return None, key_error
        source = edge["source"]
        target = edge["target"]
        if not isinstance(source, str) or not source:
            return None, _failure(
                f"graph.edges[{index}].source must be a non-empty field id string"
            )
        if not isinstance(target, str) or not target:
            return None, _failure(
                f"graph.edges[{index}].target must be a non-empty field id string"
            )
        if source not in declared:
            return None, _failure(
                f"graph.edges[{index}].source is not a declared node: {source!r}"
            )
        if target not in declared:
            return None, _failure(
                f"graph.edges[{index}].target is not a declared node: {target!r}"
            )

    return declared, None


def _validate_changed_fields(
    changed_fields: Any, declared: Set[str]
) -> Tuple[Optional[List[str]], Optional[Dict[str, Any]]]:
    if not isinstance(changed_fields, list):
        return None, _failure("changedFields must be a list of field ids")
    normalized: List[str] = []
    seen: Set[str] = set()
    for index, field_id in enumerate(changed_fields):
        if not isinstance(field_id, str) or not field_id:
            return None, _failure(
                f"changedFields[{index}] must be a non-empty field id string"
            )
        if field_id not in declared:
            return None, _failure(
                f"changedFields[{index}] is not a declared node: {field_id!r}"
            )
        if field_id not in seen:
            seen.add(field_id)
            normalized.append(field_id)
    return normalized, None


def _validate_rules(
    rules: Any, declared: Set[str]
) -> Tuple[Optional[List[Dict[str, str]]], Optional[Dict[str, Any]]]:
    if not isinstance(rules, list):
        return None, _failure("rules must be a list of rule objects")

    compiled: List[Dict[str, str]] = []
    seen_ids: Set[str] = set()
    for index, rule in enumerate(rules):
        if not isinstance(rule, dict):
            return None, _failure(f"rules[{index}] must be an object")
        key_error = _check_keys(rule, _RULE_KEYS, f"rules[{index}]")
        if key_error is not None:
            return None, key_error
        rule_id = rule["id"]
        field_id = rule["field"]
        if not isinstance(rule_id, str) or not rule_id:
            return None, _failure(
                f"rules[{index}].id must be a non-empty string"
            )
        if rule_id in seen_ids:
            return None, _failure(f"duplicate rule id: {rule_id!r}")
        if not isinstance(field_id, str) or not field_id:
            return None, _failure(
                f"rules[{index}].field must be a non-empty field id string"
            )
        if field_id not in declared:
            return None, _failure(
                f"rules[{index}].field is not a declared node: {field_id!r}"
            )
        if not isinstance(rule["description"], str) or not rule["description"]:
            return None, _failure(
                f"rules[{index}].description must be a non-empty string"
            )
        if not isinstance(rule["severity"], str) or not rule["severity"]:
            return None, _failure(
                f"rules[{index}].severity must be a non-empty string"
            )
        seen_ids.add(rule_id)
        compiled.append(
            {
                "id": rule_id,
                "field": field_id,
                "description": rule["description"],
                "severity": rule["severity"],
            }
        )
    return compiled, None


def _build_adjacency(
    edges: List[Dict[str, str]]
) -> Tuple[Dict[str, List[str]], Dict[str, List[str]]]:
    outgoing_sets: Dict[str, Set[str]] = {}
    incoming_sets: Dict[str, Set[str]] = {}
    for edge in edges:
        source = edge["source"]
        target = edge["target"]
        outgoing_sets.setdefault(source, set()).add(target)
        incoming_sets.setdefault(target, set()).add(source)
    outgoing = {source: sorted(neighbors) for source, neighbors in outgoing_sets.items()}
    incoming = {target: sorted(neighbors) for target, neighbors in incoming_sets.items()}
    return outgoing, incoming


def _shortest_distances(
    sources: List[str], outgoing: Dict[str, List[str]]
) -> Dict[str, int]:
    """Plain BFS: minimum edge count from any source to each node."""
    distances = {source: 0 for source in sources}
    queue = deque(sorted(sources))
    while queue:
        current = queue.popleft()
        next_distance = distances[current] + 1
        for nxt in outgoing.get(current, ()):
            if nxt not in distances:
                distances[nxt] = next_distance
                queue.append(nxt)
    return distances


def _lex_smallest_paths(
    sources: List[str],
    incoming: Dict[str, List[str]],
    distances: Dict[str, int],
) -> Dict[str, List[str]]:
    """Lexicographically smallest shortest path from any source per node.

    Distances come from :func:`_shortest_distances`. A shortest path to a
    node at distance ``d`` must enter from a parent at distance ``d - 1``,
    so finalizing levels in ascending distance order makes every parent's
    best path known before its children are evaluated; among same-distance
    predecessors the lexicographically smallest extended path wins. Every
    changed field seeds distance 0 with the single-node path ``[field]``.
    """
    paths: Dict[str, List[str]] = {source: [source] for source in sources}
    max_distance = max(distances.values(), default=0)
    for level in range(1, max_distance + 1):
        nodes = sorted(
            node_id for node_id, dist in distances.items() if dist == level
        )
        for node_id in nodes:
            best: Optional[List[str]] = None
            for parent in incoming.get(node_id, ()):
                if distances.get(parent) != level - 1:
                    continue
                candidate = paths[parent] + [node_id]
                if best is None or candidate < best:
                    best = candidate
            paths[node_id] = best  # type: ignore[assignment]
    return paths


def analyze_change_impact(
    graph: Any, changed_fields: Any, rules: Any
) -> Dict[str, Any]:
    """Analyze which downstream fields and rules a field change affects.

    :param graph: ``{"nodes": [...], "edges": [...]}``. Each node is an
        object with exactly the keys ``id`` (stable field id), ``object``
        (owning data object) and ``name`` (display name); node ids must be
        distinct non-empty strings. Each edge has exactly the keys
        ``source`` and ``target`` referencing declared node ids; the target
        field depends on the source field. A field may be reached by more
        than one edge and the graph may contain cycles; repeated edges are
        harmless.
    :param changed_fields: list of field ids that are changing; every id
        must be declared in ``graph.nodes``. An empty list is legal and
        yields an empty impact. Repeated ids collapse to one entry.
    :param rules: list of objects with exactly the keys ``id`` (stable rule
        id), ``field`` (the validated field id), ``description`` and
        ``severity``; rule ids must be distinct and ``field`` must be a
        declared node.
    :returns: ``{"code": "OK", "message": None, "data": {...}}`` on
        success. ``data`` contains ``changedFields`` (the sorted unique
        input ids), ``affectedFields`` (fields reachable downstream of a
        changed field, excluding changed fields themselves, sorted by id)
        and ``affectedRules`` (one object per rule whose validated field is
        reached, sorted by rule id), each with ``id``, ``field``,
        ``description``, ``severity`` and ``reasonPath``. ``reasonPath`` is
        the node-count-minimized, lexicographically smallest field-id path
        from a changed field to the rule's validated field; for a rule on a
        directly changed field it is the single-element path ``[field]``.
        Any structural or referential violation returns
        ``{"code": "INVALID_ARGUMENT", "message": str, "data": None}``; the
        message names the offending id. The same input always yields the
        same structure and ordering.
    """
    declared, graph_error = _validate_graph(graph)
    if graph_error is not None:
        return graph_error

    changed, changed_error = _validate_changed_fields(changed_fields, declared)
    if changed_error is not None:
        return changed_error

    compiled_rules, rules_error = _validate_rules(rules, declared)
    if rules_error is not None:
        return rules_error

    outgoing, incoming = _build_adjacency(graph["edges"])
    sources = sorted(set(changed))
    distances = _shortest_distances(sources, outgoing)
    paths = _lex_smallest_paths(sources, incoming, distances)

    changed_set = set(sources)
    affected_fields = sorted(
        field_id for field_id in paths if field_id not in changed_set
    )

    affected_rules: List[Dict[str, Any]] = []
    for rule in compiled_rules:
        reason_path = paths.get(rule["field"])
        if reason_path is None:
            continue
        affected_rules.append(
            {
                "id": rule["id"],
                "field": rule["field"],
                "description": rule["description"],
                "severity": rule["severity"],
                "reasonPath": reason_path,
            }
        )
    affected_rules.sort(key=lambda item: item["id"])

    return {
        "code": OK,
        "message": None,
        "data": {
            "changedFields": sources,
            "affectedFields": affected_fields,
            "affectedRules": affected_rules,
        },
    }

