            analyze_change_impact(
                payload(BASE_DATASETS, BASE_EDGES, delete("ods", "name"))
                | {"extra": 1}
            ) if False else analyze_change_impact(
                {"metadata": {"datasets": BASE_DATASETS,
                              "lineageEdges": BASE_EDGES},
                 "change": delete("ods", "name"),
                 "extra": 1}
            )

