            analyze_change_impact(
                {"metadata": {"datasets": BASE_DATASETS},
                 "change": good_change}
            )
        with self.assertRaises(ChangeImpactInputError):
            analyze_change_impact(
                {"metadata": {"datasets": [], "lineageEdges": BASE_EDGES,
                              "other": 1},
