            analyze_change_impact(
                payload({"a": [""]}, [], delete("a", "x"))
            )
        with self.assertRaises(ChangeImpactInputError):
            analyze_change_impact(
                payload({"a": [{"field": "x"}]}, [], delete("a", "x"))
            )
        with self.assertRaises(ChangeImpactInputError):
            analyze_change_impact(
                payload({"a": ["x", "x"]}, [], delete("a", "x"))
            )

